### 9. INJECTION DE CONTEXTE DANS LE CLIENT

#### Store Zustand pour l'Org Actuelle
**Fichier**: `/Users/yoannandrieux/Projets/moodday/app/orgs/[orgSlug]/use-current-org.tsx`

```typescript
type CurrentOrgStore = {
  id: string;
  slug: string;
  name: string;
  image: string | null;
  subscription: CurrentOrgPayload["subscription"] | null;
  limits: PlanLimit;
};

export const useCurrentOrg = create<CurrentOrgStore | null>(() => null);

export const InjectCurrentOrgStore = (props: PropsWithChildren<{
  org?: Omit<CurrentOrgStore, "limits">;
}>) => {
  const org = props.org;

  useEffect(() => {
    if (!org) return;
    if (useCurrentOrg.getState()) return;

    useCurrentOrg.setState((state) => ({
      ...org,
      limits: getPlanLimits(org.subscription?.plan ?? "free", null),
    }));
  }, [org]);

  return props.children;
};

// Utilisation dans les composants client
"use client";
const MyComponent = () => {
  const org = useCurrentOrg();
  return <div>Org: {org?.name}</div>;
};
```

